const fetchResults = $input.all();
const seeds = $('Prepare Seed Fetch').all();

const results = [];
for (let i = 0; i < fetchResults.length; i++) {
  const fetchResult = fetchResults[i];
  const seed = seeds[i] ? seeds[i].json : null;
  if (!seed) continue;
  if (fetchResult.json.error) continue;
  const html = fetchResult.json.data || fetchResult.json.body || '';
  if (!html || html.length < 100) continue;
  results.push({
    json: {
      html,
      source_id: seed.source_id,
      seed_url: seed._full_url || seed.url,
      seed_capability_area: seed.capability_area,
      seed_product_name: seed.product_name
    }
  });
}
return results;

// Parse Jina markdown: links in [text](url) format.
// in_seed_section is enforced as a HARD REJECT for seeds at section depth >= 2.
// Seeds at depth 0-1 (root crawls) are intentionally broad — no section filtering.

const DENY_PATTERNS = [
  '/search', '/login', '/signin', '/tag/', '/tags/', '/page/',
  '/category/', '/categories/', '/author/', '/authors/',
  '/archive/', '/archives/', '/feed', '/feeds/'
];

function getHostname(url) {
  const m = url.match(/^https?:\/\/([^\/?#]+)/i);
  return m ? m[1].toLowerCase() : '';
}

function getPathname(url) {
  const m = url.match(/^https?:\/\/[^\/?#]+([^?#]*)/i);
  return m ? m[1] : '/';
}

// Returns the seed's section prefix (directory the seed belongs to).
// Empty string = root-level seed (no strict filtering).
function getSeedSection(seedUrl) {
  const path = getPathname(seedUrl);
  if (!path || path === '/') return '';
  if (path.endsWith('/')) return path.slice(0, -1); // strip trailing slash
  const lastSlash = path.lastIndexOf('/');
  return lastSlash > 0 ? path.slice(0, lastSlash) : '';
}

const results = [];

for (const item of $input.all()) {
  const { html, seed_url, source_id, seed_capability_area, seed_product_name } = item.json;
  if (!html) continue;

  const seedHostname = getHostname(seed_url);
  const sectionPrefix = getSeedSection(seed_url);
  const sectionDepth = sectionPrefix.split('/').filter(Boolean).length;
  // Only enforce section filtering for seeds in a specific subsection (depth >= 2)
  const requireSectionMatch = sectionDepth >= 2;

  const titleMatch = html.match(/^#\s+(.+)$/m) || html.match(/^Title:\s+(.+)$/mi);
  const seedPageTitle = titleMatch ? titleMatch[1].trim() : '';

  const linkRegex = /\[([^\]]*)\]\((https?:\/\/[^\s)"']+)\)/g;
  let match;
  const seen = new Set();

  while ((match = linkRegex.exec(html)) !== null) {
    const anchorText = match[1].trim();
    const rawHref = match[2].trim();

    const linkHostname = getHostname(rawHref);
    if (!seedHostname || linkHostname !== seedHostname) continue;

    const linkPath = getPathname(rawHref).toLowerCase();
    if (DENY_PATTERNS.some(p => linkPath.includes(p))) continue;

    // HARD REJECT: links outside this seed's section
    if (requireSectionMatch && !linkPath.startsWith(sectionPrefix.toLowerCase())) continue;

    const dedupKey = (linkHostname + linkPath).replace(/\/$/, '');
    if (seen.has(dedupKey)) continue;
    seen.add(dedupKey);

    results.push({
      json: {
        raw_url: rawHref,
        anchor_text: anchorText,
        seed_source_id: source_id,
        seed_url,
        seed_capability_area,
        seed_product_name,
        seed_page_title: seedPageTitle,
        in_seed_section: true
      }
    });
  }
}

return results;

const TRACKING = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content', 'ref', 'source', 'campaign'];

function normalizeUrl(raw) {
  let url = raw.replace(/^(https?:\/\/[^\/?#]*)/i, m => m.toLowerCase());
  const fragIdx = url.indexOf('#');
  if (fragIdx !== -1) url = url.slice(0, fragIdx);
  url = url.replace(/([^/])\/($|\?)/, '$1$2');
  const qIdx = url.indexOf('?');
  if (qIdx !== -1) {
    const base = url.slice(0, qIdx);
    const kept = url.slice(qIdx + 1).split('&').filter(p => {
      const key = p.split('=')[0].toLowerCase();
      return p.length > 0 && !TRACKING.includes(key);
    });
    url = kept.length ? base + '?' + kept.join('&') : base;
  }
  return url;
}

return $input.all().map(item => ({
  json: { ...item.json, normalized_url: normalizeUrl(item.json.raw_url) }
}));

// RECLASSIFY & FILTER — v3
// v3 additions: depth ≤ 1 hard reject + cross-product root HTML patterns.

const PATH_RULES = [
