  { match: /\/sdks\/latest\/sdks\//i, product_name: 'Ping SDK', capability_area: 'DEVELOPER_PLATFORM' },
  // === PINGGATEWAY RELEASE NOTES ===
  { match: /\/pinggateway\/release-notes\//i, capability_area: 'DEVELOPER_PLATFORM' },
  // === PINGGATEWAY GENERAL OPS DOCS ===
  { match: /\/pinggateway\/[^/]+\/(about|getting-started|installation-guide|configure|scripting|logging|monitoring|clustering)\//i, reject: true },
  // === PINGONE ONBOARDING / GETTING-STARTED ===
  { match: /\/pingone\/getting_started_with_pingone\//i, reject: true },
  // === PINGONE TUTORIALS ===
  { match: /\/pingone\/pingone_tutorials\//i, reject: true },
  // === AIC USE-CASES SECTION ===
  { match: /\/pingoneaic\/use-cases\//i, reject: true },
  // === CROSS-PRODUCT DIRECTORY REJECTIONS ===
  { match: /\/pingam\//i,              reject: true },
  { match: /\/pingid-user-guide\//i,   reject: true },
  { match: /\/auth-node-ref\//i,       reject: true },
  { match: /\/solution-guides\//i,     reject: true },
  { match: /\/pingone-solutions\//i,   reject: true },
  { match: /\/enterprise-connect\//i,  reject: true },
  // === CROSS-PRODUCT ROOT HTML PAGES (v3: catches .html leakage not caught by directory patterns) ===
  { match: /\/(pingam|pingfederate|pingaccess|pingauthorize|pingdirectory|pingds|pingcentral|pingidm|pingone-solutions)\.html$/i, reject: true },
  // === AIC NON-MCP SECTIONS ===
  { match: /\/pingoneaic\/latest\/identity-governance\//i, reject: true },
  // === BLOG MARKETING RESOURCE PAGES ===
  { match: /\/resources\/(downloads|identity-fundamentals|cybersecurity-fundamentals|analyst-reports)/i, reject: true }
];

const results = [];
for (const item of $input.all()) {
  const url = item.json.normalized_url || '';

  // v3: Reject depth ≤ 1 links (root domain and single-segment paths are always low-value)
  const pathDepth = url.replace(/^https?:\/\/[^\/]+/, '').split('/').filter(Boolean).length;
  if (pathDepth <= 1) continue;

  const seedProduct = (item.json.seed_product_name || '').toLowerCase();
  let rejected = false;
  const overrides = {};

  for (const rule of PATH_RULES) {
    if (rule.match.test(url)) {
      if (rule.reject) { rejected = true; break; }
      if (rule.product_name)    overrides.seed_product_name    = rule.product_name;
      if (rule.capability_area) overrides.seed_capability_area = rule.capability_area;
      break;
    }
  }

  if (!rejected && /\/pingoneaic\/latest\//i.test(url)) {
    if (!seedProduct.includes('pingone aic')) rejected = true;
  }

  if (!rejected) results.push({ json: { ...item.json, ...overrides } });
}
return results;

const RELEASE_NOTES_RE = /\/(release-notes|changelog|whatsnew|what-is-new|whats-new)/i;
const API_RE = /\/(api\/|api-reference\/|reference\/)/i;
const INDEX_RE = /\/index(\.html)?$/i;
const SAMPLE_RE = /\/(samples\/|sample-app\/|starter\/|reference-integration\/)/i;
const PLATFORM_RE = /\/(android|ios|swift|react-native|flutter|angular|vue\/|nextjs)\//i;
const USE_CASE_RE = /\/(use-case|guide\/|how-to|tutorial\/)/i;

function classify(normalizedUrl) {
  const path = normalizedUrl.toLowerCase();
  if (RELEASE_NOTES_RE.test(path)) return { source_role: 'release_notes', suggested_priority: 'P1', is_authoritative: true };
  if (API_RE.test(path))           return { source_role: 'api_reference',  suggested_priority: 'P2', is_authoritative: false };
  if (INDEX_RE.test(path))         return { source_role: 'family_index',   suggested_priority: 'P3', is_authoritative: false };
  if (SAMPLE_RE.test(path))        return { source_role: 'sample_only',    suggested_priority: 'P3', is_authoritative: false };
  if (PLATFORM_RE.test(path))      return { source_role: 'platform_specific', suggested_priority: 'P2', is_authoritative: false };
  if (USE_CASE_RE.test(path))      return { source_role: 'use_case',       suggested_priority: 'P2', is_authoritative: false };
  // Fallback: no pattern matched — mark as unknown for Claude enrichment
  return { source_role: 'unknown', suggested_priority: 'P2', is_authoritative: false };
}

return $input.all().map(item => {
  const c = classify(item.json.normalized_url);
  return {
    json: {
      ...item.json,
      source_role: c.source_role,
      suggested_priority: c.suggested_priority,
      is_authoritative_classification: c.is_authoritative,
      classification_source: c.source_role === 'unknown' ? 'rules_uncertain' : 'rules'
    }
  };
});

const cfg = $('Discovery Config').first().json;
const useClaudeClassification = cfg.USE_CLAUDE_CLASSIFICATION === true;
const maxCandidates = typeof cfg.MAX_CLAUDE_CANDIDATES_PER_RUN === 'number'
  ? cfg.MAX_CLAUDE_CANDIDATES_PER_RUN
  : 200;

// Only unknown items (rules couldn't classify) are candidates for Claude.
// Cap applies only to those — confidently-classified items always skip Claude.
let claudeCount = 0;
return $input.all().map(item => {
  const needsClassification = item.json.source_role === 'unknown';
  const withinCap = claudeCount < maxCandidates;
  const skipClaude = !needsClassification || !useClaudeClassification || !withinCap;
  if (!skipClaude) claudeCount++;
  return {
    json: {
      ...item.json,
      classification_source: !skipClaude ? 'claude' : item.json.classification_source,
      _skip_claude: skipClaude
    }
  };
});

const KNOWN_CAPABILITY_TAGS = [
  'hosted_pages', 'login_widget', 'sdk', 'javascript_sdk', 'mobile_sdk',
  'biometrics', 'passkeys', 'mfa', 'social_login', 'magic_links', 'in_app_sso',
  'device_profiling', 'mcp', 'mcp_gateway', 'ai_agents', 'a2a_protocol',
  'token_exchange', 'token_vault', 'oidc_sdk', 'davinci_sdk', 'authenticator_module',
  'journey_nodes', 'end_user_ui', 'design_system', 'release_notes', 'api_reference',
  'sample_app', 'astro', 'flutter', 'android_sdk', 'ios_sdk'
];

return $input.all().map(item => {
  const i = item.json;
  const titleInfo = i.seed_page_title ? `\nPage title of seed: "${i.seed_page_title}"` : '';
  const anchorInfo = i.anchor_text ? `\nAnchor text: "${i.anchor_text}"` : '';

  const prompt = `You are classifying a documentation page discovered from a Ping Identity product index.\n\nSeed page: ${i.seed_url}\nProduct: ${i.seed_product_name}${titleInfo}\nCandidate URL: ${i.normalized_url}${anchorInfo}\n\nAssign:\n1. source_role — one of: capability_definition | platform_specific | use_case | release_notes | api_reference | sample_only | family_index\n2. capability_tag — one of: ${KNOWN_CAPABILITY_TAGS.join(' | ')}\n3. confidence — integer 1–5\n\nRules:\n- If you cannot determine source_role or capability_tag with confidence >= 3, return not_enough_context: true\n- Do not infer from URL alone if anchor text contradicts it\n- Return JSON only: {"source_role":"...","capability_tag":"...","confidence":N,"not_enough_context":false}`;

  return { json: { ...i, _claude_prompt: prompt } };
});

const claudeResponses = $input.all();
const originalItems = $('Format Claude Prompt').all();

return claudeResponses.map((response, i) => {
  const original = (originalItems[i] || { json: {} }).json;
  const rulesRole = original.source_role;
  const isAuthoritative = original.is_authoritative_classification;

  let claudeResult = null;
  try {
    const rawContent = response.json.content?.[0]?.text || '';
    const jsonMatch = rawContent.match(/\{[\s\S]*\}/);
    if (jsonMatch) claudeResult = JSON.parse(jsonMatch[0]);
  } catch (e) {}

  if (!claudeResult || claudeResult.not_enough_context) {
    const { _claude_prompt, _skip_claude, ...rest } = original;
    return { json: { ...rest, classification_source: 'rules' } };
  }

  const claudeRole = claudeResult.source_role;
  const claudeTag = claudeResult.capability_tag;
  const claudeConf = claudeResult.confidence || 0;

  let finalRole = rulesRole;
  let finalTag = claudeTag || '';
  let classificationSource = 'rules';

  if (claudeRole === rulesRole) {
    finalRole = claudeRole;
    classificationSource = 'claude_assisted';
  } else {
    const overrideThreshold = isAuthoritative ? 5 : 4;
    if (claudeConf >= overrideThreshold) {
      finalRole = claudeRole;
      classificationSource = 'claude_override';
    } else {
      finalRole = rulesRole;
      finalTag = claudeConf >= 3 ? (claudeTag || '') : '';
      classificationSource = 'rules';
    }
  }

  const { _claude_prompt, _skip_claude, ...rest } = original;
  return { json: { ...rest, source_role: finalRole, capability_tag: finalTag, classification_source: classificationSource } };
});

const now = new Date().toISOString();

const existingRows = $input.all().map(item => item.json);
const existingUrlMap = new Map();
existingRows.forEach(row => {
  if (row.url) existingUrlMap.set(row.url.trim(), row);
});

const candidates = $('Rejoin Classification Paths').all();
const results = [];

for (const item of candidates) {
  const url = item.json.normalized_url;
  const existing = existingUrlMap.get(url);

  if (existing) {
    results.push({
      json: { _action: 'update_metadata', url, last_seen: now, last_checked: now }
    });
  } else {
    const slug = url
      .replace(/^https?:\/\/[^\/]+/, '')
      .replace(/[^a-z0-9]+/gi, '-')
      .toLowerCase()
      .slice(0, 40)
      .replace(/^-+|-+$/g, '');
    const sourceId = `disc-${item.json.seed_source_id}-${slug}`;
    results.push({
      json: {
        _action: 'insert_candidate',
        source_id: sourceId,
        parent_source_id: item.json.seed_source_id,
        product_name: item.json.seed_product_name,
        capability_area: item.json.seed_capability_area,
        capability_tag: item.json.capability_tag || '',
        source_type: 'documentation',
        source_role: item.json.source_role,
        priority: item.json.suggested_priority,
        status: 'candidate',
        url,
        discovered_from_url: item.json.seed_url,
        discovered_at: now,
        last_seen: now,
        last_checked: now,
        classification_source: item.json.classification_source,
        notes: ''
      }
    });
  }
}

return results;

return $input.all().map(item => {
  const { _action, ...rest } = item.json;
  return { json: rest };
});
